create or replace function public.delete_developer_client_property_rc1(p_client_id uuid,p_property_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501'; end if; if not exists(select 1 from public.properties where id=p_property_id and client_id=p_client_id) then raise exception 'PROPERTY_NOT_FOUND' using errcode='22023'; end if; if exists(select 1 from public.marketplace_jobs where property_id=p_property_id) then return jsonb_build_object('deleted',false,'reason','mission_history_exists'); end if; delete from public.properties where id=p_property_id and client_id=p_client_id; return jsonb_build_object('deleted',true); end; $$;
revoke all on function public.delete_developer_client_property_rc1(uuid,uuid) from public,anon;
grant execute on function public.delete_developer_client_property_rc1(uuid,uuid) to authenticated,service_role;
